   [1]={next_id=2, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The orphanage was my entire world. The children. The elderly nuns. The stray animals. That was all I knew.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id=1009, background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, update_model={}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [2]={next_id=3, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="When I left, the Knights and the library became my new world—but it was still just a box. No matter what filled it, the walls remained.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id=0, background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, update_model={}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
