   [5]={next_id=6, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Black trees abruptly grew from the soil, without branches or leaves, standing like landmarks. The aurora flowed down along the trees, soaking into the ground like water, scattering with every step I took, only to converge again.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id=0, background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, update_model={}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
